const SKIN15_BG="data:image/webp;base64,";setInterval(()=>{try{for(const [k,v] of [["missions","ic-missions"],["endless","ic-endless"],["chest","ic-chest"]]){const e=document.querySelector('#hgr41 .h1-ribbon [data-go="'+k+'"]');if(e&&!e.dataset.u15){e.dataset.u15=1;e.style.setProperty("background","var(--u15-"+v+") "+(k==="chest"?"8px center/auto 66%":"center 3px/auto 58%")+" no-repeat,linear-gradient(#1c4a70e6,#0a2038e6)","important");}}}catch(_){}},700);